(inputs) => { const input = inputs;
  if (!Array.isArray(input.events) || input.events.length > 5000) throw new Error('Supply at most 5000 normalised outcome events.');
  if (!Number.isInteger(input.minimum_delivered) || input.minimum_delivered < 1) throw new Error('Set minimum_delivered before examining results.');
  const groups = new Map(), people = new Map(), seen = new Map();
  for (const e of input.events) {
    for (const key of ['event_id','enrollment_id','test_round','group_id','variant_id','prompt_version','event']) if (typeof e[key] !== 'string' || !e[key]) throw new Error('Event missing ' + key);
    if (!['delivered','positive_reply','meeting_booked'].includes(e.event)) throw new Error('Unsupported event: ' + e.event);
    const canonical = JSON.stringify([e.enrollment_id,e.test_round,e.group_id,e.variant_id,e.prompt_version,e.event]);
    if (seen.has(e.event_id)) { if (seen.get(e.event_id) !== canonical) throw new Error('Conflicting duplicate event ID.'); continue; }
    seen.set(e.event_id, canonical);
    const key = JSON.stringify([e.test_round,e.group_id,e.variant_id,e.prompt_version]);
    if (people.has(e.enrollment_id) && people.get(e.enrollment_id) !== key) throw new Error('Enrollment changed treatment inside the supplied results.');
    people.set(e.enrollment_id,key);
    if (!groups.has(key)) groups.set(key,{test_round:e.test_round,group_id:e.group_id,variant_id:e.variant_id,prompt_version:e.prompt_version,delivered:new Set(),positive_reply:new Set(),meeting_booked:new Set()});
    groups.get(key)[e.event].add(e.enrollment_id);
  }
  const cohorts = [...groups.values()].map(g => {
    // Count outcomes only for delivered enrollments in this same cohort.
    const positives = [...g.positive_reply].filter(id => g.delivered.has(id)).length;
    const meetings = [...g.meeting_booked].filter(id => g.delivered.has(id)).length;
    const delivered = g.delivered.size;
    return {test_round:g.test_round,group_id:g.group_id,variant_id:g.variant_id,prompt_version:g.prompt_version,delivered,positive_replies:positives,meetings,positive_reply_rate:delivered ? positives / delivered : null,meeting_rate:delivered ? meetings / delivered : null,enough_data:delivered >= input.minimum_delivered,orphan_outcomes:[...new Set([...g.positive_reply,...g.meeting_booked])].filter(id => !g.delivered.has(id)).length};
  });
  return {cohorts,review_required:true,note:'Rates are descriptive. A sample floor is not statistical significance. Compare within round, group and prompt version; review a proposed rule change before changing ICP, offer or copy.'};
}

(inputs) => { const input = inputs;
  const { account_key, test_round, group_id, prompt_version, variants } = input;
  for (const [key, value] of Object.entries({account_key,test_round,group_id,prompt_version})) if (typeof value !== 'string' || !value.trim()) throw new Error(key + ' is required.');
  if (!Array.isArray(variants) || variants.length !== 2 || variants.some(v => typeof v !== 'string' || !v.trim()) || variants[0] === variants[1]) throw new Error('Exactly two distinct variant IDs are required.');
  // Frozen, deterministic FNV-1a bucketing. The company is the randomisation unit:
  // colleagues in one account receive the same treatment. Never change salt/order mid-round.
  const key = JSON.stringify([test_round.trim(), group_id.trim(), account_key.trim().toLowerCase().replace(/^www\./, '')]);
  let hash = 2166136261;
  for (let i = 0; i < key.length; i++) { hash ^= key.charCodeAt(i); hash = Math.imul(hash, 16777619) >>> 0; }
  return { test_round, group_id, variant_id: variants[hash % 2], prompt_version, assignment_key: key, algorithm: 'fnv1a-account-v1' };
}

(inputs) => { const input = inputs;
  if (!Array.isArray(input.records) || input.records.length > 1000) throw new Error('Supply at most 1000 source records.');
  const seen = new Map();
  const rejected = [];
  for (const record of input.records) {
    const raw = String(record.company_domain || '').trim().toLowerCase();
    const domain = raw.replace(/^[a-z][a-z0-9+.-]*:\/\//, '').split(/[/?#]/)[0].replace(/^www\./, '').replace(/:\d+$/, '');
    const validDomain = /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(domain);
    const time = record.observed_at_ms;
    if (!validDomain || !Number.isSafeInteger(time) || time < 0 || !record.source || !record.signal_type) {
      rejected.push({ id: String(record.id || raw), reason: 'Missing or invalid domain, source, signal type or timestamp.' });
      continue;
    }
    const event = { source: String(record.source), signal_type: String(record.signal_type), observed_at_ms: time };
    if (!seen.has(domain)) seen.set(domain, { company_domain: domain, signals: [] });
    const account = seen.get(domain);
    if (!account.signals.some(s => s.source === event.source && s.signal_type === event.signal_type && s.observed_at_ms === time)) account.signals.push(event);
  }
  return { accounts: [...seen.values()].sort((a,b) => a.company_domain.localeCompare(b.company_domain)), rejected };
}

(inputs) => { const input = inputs;
  const reasons = [];
  const score = x => typeof x === 'number' && Number.isFinite(x) && x >= 0 && x <= 100;
  if(input.company_disqualified !== false || input.persona_disqualified !== false) reasons.push('A disqualification is present or has not been checked.');
  if (!score(input.company_threshold) || !score(input.persona_threshold)) throw new Error('Valid thresholds required.');
  if (!score(input.company_score) || input.company_score < input.company_threshold) reasons.push('Company fit failed.');
  if (!score(input.persona_score) || input.persona_score < input.persona_threshold) reasons.push('Persona fit failed.');
  if (typeof input.email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.email)) reasons.push('Missing work email.');
  if (input.email_status !== 'valid') reasons.push('Email must have a valid verification result.');
  const validTimes = Number.isSafeInteger(input.as_of_ms) && input.as_of_ms >= 0 && Number.isSafeInteger(input.verified_at_ms) && input.verified_at_ms >= 0;
  const age = validTimes ? (input.as_of_ms - input.verified_at_ms) / 86400000 : -1;
  if (!Number.isFinite(input.max_verification_age_days) || input.max_verification_age_days <= 0 || !Number.isFinite(age) || age < 0 || age > input.max_verification_age_days) reasons.push('Verification is missing, future-dated or stale.');
  if (input.reviewed !== true) reasons.push('First touch has not been reviewed.');
  if (input.suppressed !== false) reasons.push('Suppression status must be explicitly clear.');
  if (!Number.isInteger(input.remaining_capacity) || input.remaining_capacity < 1) reasons.push('No capacity.');
  for (const key of ['sequence_id','test_round','group_id','variant_id','prompt_version','subject','body']) if (typeof input[key] !== 'string' || !input[key].trim()) reasons.push(key + ' is missing.');
  return { ready: reasons.length === 0, reasons, sequence_id: String(input.sequence_id || ''), email: String(input.email || ''), subject: String(input.subject || ''), body: String(input.body || ''), test_round: String(input.test_round || ''), group_id: String(input.group_id || ''), variant_id: String(input.variant_id || ''), prompt_version: String(input.prompt_version || '') };
}

(inputs) => { const input = inputs;
  const { candidates, company_threshold, persona_threshold, capacity, as_of_ms, max_signal_age_days, mode } = input;
  if (!Array.isArray(candidates) || candidates.length > 1000) throw new Error('Supply at most 1000 candidates.');
  if (!['accounts', 'contacts'].includes(mode)) throw new Error('mode must be accounts or contacts');
  if (!Number.isInteger(capacity) || capacity < 0 || capacity > 1000) throw new Error('capacity must be 0..1000');
  const score = x => typeof x === 'number' && Number.isFinite(x) && x >= 0 && x <= 100;
  if (!score(company_threshold) || !score(persona_threshold)) throw new Error('Thresholds must be 0..100.');
  const now = as_of_ms;
  if (!Number.isSafeInteger(now) || now < 0 || !Number.isFinite(max_signal_age_days) || max_signal_age_days <= 0) throw new Error('A valid as_of_ms and positive signal lifetime are required.');
  const eligible = [], held = [], ids = new Set();
  for (const c of candidates) {
    if (typeof c.id !== 'string' || !c.id || ids.has(c.id)) throw new Error('Each candidate must have a unique id.');
    ids.add(c.id);
    if (c.company_disqualified !== false || !score(c.company_score) || c.company_score < company_threshold || (mode === 'contacts' && (c.persona_disqualified !== false || !score(c.persona_score) || c.persona_score < persona_threshold))) {
      held.push({ id: c.id, reason: 'Fit gate failed or required score missing.' }); continue;
    }
    if (c.suppressed === true) { held.push({ id: c.id, reason: 'Suppressed.' }); continue; }
    const age = Number.isSafeInteger(c.observed_at_ms) && c.observed_at_ms >= 0 ? (now - c.observed_at_ms) / 86400000 : -1;
    const intent = score(c.signal_strength) && Number.isFinite(age) && age >= 0 && age <= max_signal_age_days ? c.signal_strength * (1 - age / max_signal_age_days) : 0;
    const fit = mode === 'contacts' ? (c.company_score + c.persona_score) / 2 : c.company_score;
    eligible.push({ id: c.id, priority: Math.round((0.7 * fit + 0.3 * intent) * 100) / 100, intent_score: Math.round(intent * 100) / 100, reason: '70% fit + 30% freshness-adjusted intent; passed independent fit gates.' });
  }
  eligible.sort((a,b) => b.priority - a.priority || a.id.localeCompare(b.id));
  for (const c of eligible.slice(capacity)) held.push({ id: c.id, reason: 'Outside this run’s capacity.' });
  return { selected: eligible.slice(0, capacity), held };
}

